// Using the printToScreen() function, print all of the powers of 3 that are less than 5000

// Solution

for (let i = 1; i < 5000; i *= 3) {
  printToScreen(i);
}

// DO NOT ALTER CODE WRITTEN BELOW THIS LINE

function printToScreen(text) {
  let r = Math.floor((Math.random() * 155));
  let g = Math.floor((Math.random() * 155));
  let b = Math.floor((Math.random() * 155));
  const svg = d3.select("body")
    .append("svg")
    .attr("width", 1500)
    .attr("height", 75);

  svg.append("text")
    .attr("y", 37.5)
    .attr("width", 450)
    .attr("height", 75)
    .attr("x", -1000)
    .attr("font-weight", "bold")
    .attr("font-size", "30px")
    .attr("fill", `rgb(${r},${g},${b}`)
    .attr("font-family", "Times New Roman")
    .text(text)
    .transition()
    .duration(1000)
    .attr("x", 37.5);
}

// Get a word from the user and then use printToScreen() and for loops to print every letter of that word. Next, print every letter of the same word backwards using while loops.

// Solution

let word = prompt("Please enter a word.");

for (let i = 0; i < word.length; i++) {
  printToScreen(word[i]);
}

let counter = word.length - 1;
while (counter > -1){
  printToScreen(word[counter]);
  counter--;
}

